input.command:
Write-Output "--- plugins dir"; Get-ChildItem "$env:APPDATA\Blockbench\plugins" -ErrorAction SilentlyContinue | Select Name,Length,LastWriteTime | Format-Table -Auto
Write-Output "--- blockbench process"; Get-Process | ? { $_.ProcessName -match 'blockbench' } | Select Id,ProcessName
Write-Output "--- listening ports"; Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | ? { $_.LocalPort -in 3000,3001,6280,8080 } | Select LocalAddress,LocalPort,OwningProcess
Write-Output "--- mcp config"; claude mcp list 2>&1 | Select-String -Pattern 'blockbench|bb-mcp|Error' 
Get-ChildItem -Path . -Filter .mcp.json -Force -ErrorAction SilentlyContinue | % { Get-Content $_.FullName }
Write-Output "--- endpoint"; try { (Invoke-WebRequest -Uri http://localhost:3000/bb-mcp -UseBasicParsing -TimeoutSec 3).StatusCode } catch { $_.Exception.Message }
